function validate([employees, id]) {
  if (!Array.isArray(employees) || employees.length < 1 || employees.length > 2000) return 'employees needs 1 to 2000 entries.';
  const manager = new Map();
  const ids = new Set();
  for (const entry of employees) {
    if (!Array.isArray(entry) || entry.length !== 3 || !Array.isArray(entry[2])) return 'Write each employee as [id, importance, subordinates].';
    const [own, importance] = entry;
    if (!Number.isInteger(own) || own < 1 || own > 2000) return 'Employee ids are whole numbers from 1 to 2000.';
    if (ids.has(own)) return 'Employee ids must be unique.';
    ids.add(own);
    if (!Number.isInteger(importance) || importance < -100 || importance > 100) return 'Importance values are whole numbers from -100 to 100.';
  }
  for (const [own, , subordinates] of employees) {
    for (const sub of subordinates) {
      if (!ids.has(sub)) return 'Every subordinate id must belong to an employee.';
      if (manager.has(sub)) return 'An employee can have at most one direct manager.';
      manager.set(sub, own);
    }
  }
  // With one manager each, the lines are loop-free exactly when walking down from the top people reaches everyone.
  const byId = new Map(employees.map(entry => [entry[0], entry[2]]));
  const stack = [...ids].filter(own => !manager.has(own));
  let reached = 0;
  while (stack.length > 0) {
    reached++;
    for (const sub of byId.get(stack.pop())) stack.push(sub);
  }
  if (reached !== employees.length) return 'The reporting lines must not form a loop.';
  if (!ids.has(id)) return 'id must be the id of one of the employees.';
  return null;
}

