function adapt(input, solve, kit) {
  const [list, id] = input;
  class Employee {
    constructor(id, importance, subordinates) { this.id = id; this.importance = importance; this.subordinates = subordinates; }
  }
  const employees = list.map(([own, importance, subordinates]) => new Employee(own, importance, [...subordinates]));
  const result = solve(employees, id);
  if (result === undefined) throw new Error('The solution did not return a value.');
  return result;
}

