function getImportance(employees, id) {
  // Walk up from every employee through their managers and count those whose chain passes through id.
  const managerOf = {};
  for (const person of employees) {
    for (const sub of person.subordinates) managerOf[sub] = person.id;
  }
  let sum = 0;
  for (const person of employees) {
    let current = person.id;
    while (current !== undefined && current !== id) current = managerOf[current];
    if (current === id) sum += person.importance;
  }
  return sum;
}

