function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const shuffle = (list) => {
    for (let i = list.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [list[i], list[j]] = [list[j], list[i]];
    }
    return list;
  };
  const n = size === 'large' ? int(1800, 2000) : int(1, 9);
  const idPool = size === 'large' || rand() < 0.3 ? 2000 : 20;
  const ids = shuffle(Array.from({ length: idPool }, (_, i) => i + 1)).slice(0, n);
  const span = size === 'small' && rand() < 0.5 ? 5 : 100;
  const shape = rand();
  const subordinates = ids.map(() => []);
  for (let i = 1; i < n; i++) {
    // Shapes: a long chain, a wide star, or a random forest where some people have no manager.
    if (shape < 0.2) subordinates[i - 1].push(ids[i]);
    else if (shape < 0.35) subordinates[0].push(ids[i]);
    else if (rand() < 0.9) subordinates[int(0, i - 1)].push(ids[i]);
  }
  const employees = shuffle(ids.map((own, i) => [own, int(-span, span), shuffle(subordinates[i])]));
  // Large cases usually ask about the top of a big tree; small ones ask about anyone.
  const id = size === 'large' && rand() < 0.7 ? ids[0] : ids[int(0, n - 1)];
  return [employees, id];
}
